def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    dangerous_prev = 0.0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev.get('bid', 0.0)
                prev_bids.append(bid)
                if bid > dangerous_prev:
                    dangerous_prev = bid

    slots = int(supply / WATER_REQ)
    if slots < 0:
        slots = 0

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return min(budget, 18.0)

    opp_count = len(alive_opponents)

    urgent = False
    if hp <= 3 or no_water_days >= 2:
        urgent = True
    elif hp <= 5 and no_water_days >= 1:
        urgent = True

    if slots >= opp_count + 1:
        base = 8.0
    elif slots >= 2:
        base = 24.0
    else:
        base = 46.0

    if prev_bids:
        high_prev = max(prev_bids)
        low_prev = min(prev_bids)
        avg_prev = sum(prev_bids) / float(len(prev_bids))
    else:
        high_prev = 0.0
        low_prev = 0.0
        avg_prev = 0.0

    target = base

    if slots >= 2:
        if high_prev >= 95:
            target = max(target, 28.0)
        elif high_prev >= 75:
            target = max(target, 34.0)
        else:
            target = max(target, 26.0)
    else:
        if high_prev >= 95:
            target = max(target, 72.0)
        elif high_prev >= 75:
            target = max(target, 63.0)
        else:
            target = max(target, 55.0)

    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        obudget = opp.get('budget', 0.0)
        ohp = opp.get('hp', 0)
        ono = opp.get('no_water_days', 0)
        oreq = opp.get('water_requirement', WATER_REQ)
        if prev and prev.get('bid') is not None:
            pbid = prev.get('bid', 0.0)
            if pbid >= 90 and obudget > budget and slots <= 1:
                target += 3.0
            if ohp <= 3 or ono >= 2:
                target += 2.0
            if oreq > WATER_REQ and slots >= 2:
                target -= 1.0

    if urgent:
        if slots >= 2:
            target = max(target, min(68.0, high_prev + 2.0 if high_prev > 0 else 52.0))
        else:
            target = max(target, min(95.0, high_prev + 3.0 if high_prev > 0 else 78.0))
    else:
        if hp >= 8 and no_water_days == 0 and high_prev >= 90 and slots >= 2:
            target = min(target, 22.0)

    if budget < DAILY_SALARY:
        target = min(target, budget * 0.9)

    if hp <= 2:
        target = max(target, min(budget, 96.0))
    elif hp <= 4 and no_water_days >= 1:
        target = max(target, min(budget, 82.0))

    if target < 0:
        target = 0.0

    return float(min(budget, round(target, 2)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    available_water_packages = int(day_context['supply'] // WATER_REQ)

    # Base bid strategy based on personal health
    if my_status['no_water_days'] > 0 or my_status['hp'] <= 2:
        my_bid = DAILY_SALARY * 1.05  # Very aggressive if critical
    elif my_status['hp'] <= 4:
        my_bid = DAILY_SALARY * 0.9   # Aggressive if low health
    else:
        my_bid = DAILY_SALARY * 0.65  # Moderate if healthy

    # Adjust based on supply scarcity vs. total bidders
    total_bidders = num_alive_opponents + 1
    if available_water_packages < total_bidders:
        # High competition: Not enough water for everyone
        if my_status['no_water_days'] > 0 or my_status['hp'] <= 4:
            my_bid *= 1.1  # Increase bid significantly if desperate
        else:
            my_bid *= 1.05 # Increase moderately
    elif available_water_packages >= total_bidders + 1:
        # Low competition: More than enough water for everyone
        if my_status['hp'] > 5:
            my_bid *= 0.9  # Try to save money if healthy
        else:
            my_bid *= 0.95 # Slight reduction if not perfectly healthy

    # Analyze yesterday's bids from opponents to adjust
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # If highest previous bid was very high and I need water, I must outbid.
        if highest_prev_bid >= DAILY_SALARY * 0.9 and (my_status['no_water_days'] > 0 or my_status['hp'] <= 4):
            my_bid = max(my_bid, highest_prev_bid + 5)
        # If opponents are generally bidding high, but I'm not desperate, try to outbid slightly.
        elif highest_prev_bid >= DAILY_SALARY * 0.7:
            my_bid = max(my_bid, highest_prev_bid + 1)
        # If opponents are bidding low, ensure I win cheaply
        elif highest_prev_bid < DAILY_SALARY * 0.4:
            my_bid = max(my_bid, highest_prev_bid + 1)

    # Cap the bid at my current budget
    final_bid = min(my_bid, my_status['budget'])

    # Ensure a minimum bid if I have budget and need water, unless it's the last day and I'm very healthy
    if final_bid <= 0 and my_status['budget'] > 0 and my_status['hp'] < EPISODE_DAYS:
        final_bid = 1.0 

    # If budget is zero, I cannot bid
    if my_status['budget'] <= 0:
        return 0.0

    return final_bid

